/**
 * plugins/requestId.ts — Request ID propagation
 *
 * For every incoming request:
 *   1. Reads X-Request-ID header if provided (trusts upstream proxy / client).
 *   2. Falls back to a UUID v4 generated by Fastify's built-in genReqId.
 *   3. Echoes the ID back in the X-Request-ID response header.
 *   4. Binds the ID to all log entries via child logger.
 */

import fp from 'fastify-plugin';
import type { FastifyInstance } from 'fastify';
import { randomUUID } from 'node:crypto';

async function requestIdPluginFn(app: FastifyInstance): Promise<void> {
  // Override Fastify's request ID generator:
  // honour client-supplied X-Request-ID, otherwise generate a UUID.
  app.addHook('onRequest', async (request, reply) => {
    const incoming = request.headers['x-request-id'];
    const id =
      typeof incoming === 'string' && incoming.length > 0
        ? incoming
        : randomUUID();

    // Attach to the request object so downstream handlers can reference it
    (request as typeof request & { requestId: string }).requestId = id;

    // Bind to pino child logger so every log line carries request_id
    request.log = request.log.child({ requestId: id });

    // Echo back in response
    void reply.header('x-request-id', id);
  });
}

export const requestIdPlugin = fp(requestIdPluginFn, {
  name: 'request-id',
  fastify: '5.x',
});
